import { useTheme } from '../../hooks/useTheme';

export default function IconButton({ onClick, title, children, active = false, danger = false, style = {} }) {
  const { hoverHex, textHex, mutedHex } = useTheme();
  return (
    <button
      onClick={onClick}
      title={title}
      style={{
        background: 'none', border: 'none', cursor: 'pointer',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        borderRadius: 8, padding: 6, transition: 'background 0.15s, color 0.15s',
        color: danger ? '#ef4444' : active ? '#6366f1' : mutedHex,
        ...style,
      }}
      onMouseEnter={(e) => { e.currentTarget.style.background = hoverHex; e.currentTarget.style.color = textHex; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = 'none';   e.currentTarget.style.color = danger ? '#ef4444' : active ? '#6366f1' : mutedHex; }}
    >
      {children}
    </button>
  );
}
